@* Displays a single task card with move buttons *@

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge @PriorityClass">@Task.Priority</span>
    <p class="due-date">@Task.DueDate.ToString("MMM dd")</p>
    <div class="card-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };
}

@* Inline form for adding a new task to a column *@

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave">Save</button>
        <button class="btn-cancel" @onclick="OnCancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<NewTaskModel> OnSave { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnCancel { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
        title = "";
        assignee = "";
        priority = "Medium";
        dueDate = DateTime.Today;
    }

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@* A single Kanban column showing tasks and an add form *@

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName (@Tasks.Count)</h3>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowLeftButton"
                      ShowMoveRight="ShowRightButton"
                      OnMoveLeft="() => OnMoveLeft.InvokeAsync(task.Id)"
                      OnMoveRight="() => OnMoveRight.InvokeAsync(task.Id)" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm OnSave="HandleSave" OnCancel="() => showForm = false" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = "";

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowLeftButton { get; set; }

    [Parameter]
    public bool ShowRightButton { get; set; }

    [Parameter]
    public EventCallback<int> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<int> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showForm = false;
    }
}

@* Summary stats bar for the board *@

<div class="board-stats">
    <span class="stat">Total: @Total</span>
    <span class="stat">To Do: @ToDo</span>
    <span class="stat">In Progress: @InProgress</span>
    <span class="stat">Done: @Done</span>
    <span class="stat stat-overdue">Overdue: @Overdue</span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int ToDo { get; set; }
    [Parameter] public int InProgress { get; set; }
    [Parameter] public int Done { get; set; }
    [Parameter] public int Overdue { get; set; }
}

@* Search bar for filtering tasks by title *@

<div class="task-search">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = "";

    [Parameter]
    public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await SearchTextChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (loading)
{
    <p>Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Total="allTasks.Count"
                ToDo="todoTasks.Count"
                InProgress="inProgressTasks.Count"
                Done="doneTasks.Count"
                Overdue="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <TaskSearch SearchText="@searchText" SearchTextChanged="HandleSearch" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="filteredTodo"
                      ShowLeftButton="false"
                      ShowRightButton="true"
                      OnMoveRight="id => MoveTask(id, \"In Progress\")"
                      OnAddTask="model => AddTask(model, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="filteredInProgress"
                      ShowLeftButton="true"
                      ShowRightButton="true"
                      OnMoveLeft="id => MoveTask(id, \"To Do\")"
                      OnMoveRight="id => MoveTask(id, \"Done\")"
                      OnAddTask="model => AddTask(model, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="filteredDone"
                      ShowLeftButton="true"
                      ShowRightButton="false"
                      OnMoveLeft="id => MoveTask(id, \"In Progress\")"
                      OnAddTask="model => AddTask(model, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool loading = true;
    private string? errorMessage;
    private string searchText = "";

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> filteredTodo => Filter(todoTasks);
    private List<TaskItem> filteredInProgress => Filter(inProgressTasks);
    private List<TaskItem> filteredDone => Filter(doneTasks);

    private List<TaskItem> Filter(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText)) return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearch(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            allTasks = allTasks.Select(t => t.Id == taskId ? task with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}

