.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.board-stats .stat {
    font-weight: 600;
    padding: 0.25rem 0.75rem;
    background: #e9ecef;
    border-radius: 4px;
}

.board-stats .stat-overdue {
    background: #f8d7da;
    color: #842029;
}

.task-search {
    margin-bottom: 1rem;
}

.task-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 1rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

.column-header h3 {
    margin: 0 0 1rem 0;
    font-size: 1.1rem;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-card h4 {
    margin: 0 0 0.5rem 0;
    font-size: 0.95rem;
}

.task-card .assignee {
    margin: 0 0 0.25rem 0;
    color: #6c757d;
    font-size: 0.85rem;
}

.task-card .due-date {
    margin: 0.25rem 0;
    font-size: 0.85rem;
    color: #495057;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 3px;
    font-size: 0.75rem;
    font-weight: 600;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.card-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    border: 1px solid #6c757d;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 4px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.9rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
